final case class TokenFunctor[+T](private val opt: Option[T]) {
  def map[U](f: T => U): TokenFunctor[U] = TokenFunctor(opt.map(f))

  def flatMap[U](f: T => TokenFunctor[U]): TokenFunctor[U] =
