      if (!ok) throw new IllegalArgumentException(s"Validation failed for $value")

      val normalized = ns.foldLeft(value.toString)((acc, n) => n(acc))
      Token(normalized, TokenType.String, meta)
    }
  }

  def buildEither(): T => Either[String, Token] = {
    val f = build()
    (value: T) => Try(f(value)).toEither.left.map(_.getMessage)
  }
}

