final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)

  def withMetadataMap(extra: Map[String, Any]): Token =
    copy(metadata = metadata ++ extra)
}

final class MutableTokenBatch(initial: Seq[Token] = Seq.empty) {
  private val buffer: mutable.ListBuffer[Token] = mutable.ListBuffer.from(initial)
  private var processed: Boolean = false

  def tokens: List[Token] = buffer.toList

  def add(token: ***REDACTED*** Unit = {
    if (processed) throw new IllegalStateException("Batch already processed")
    buffer += token
  }

  def markProcessed(): Unit = processed = true
}

