    String.format(java.util.Locale.ROOT, s"%.${precision}f", java.lang.Double.valueOf(d))

  private def formatDecimal(d: BigDecimal): String = {
    val scaled = d.setScale(precision, BigDecimal.RoundingMode.HALF_UP)
