final case class TokenMonad[+T](private val opt: Option[T]) {
  def map[U](f: T => U): TokenMonad[U] = TokenMonad(opt.map(f))

  def flatMap[U](f: T => TokenMonad[U]): TokenMonad[U] =
    TokenMonad(opt.flatMap(t => f(t).opt))

  def getOrElse[U >: T](default: => U): U = opt.getOrElse(default)

  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] =
    TokenMonad(for {
      f <- funcWrapped.opt
      v <- opt
    } yield f(v))
}

