private object JsonRenderer {
  private def escapeString(s: String): String = {
    val sb = new StringBuilder(s.length + 16)
    sb.append('"')
    s.foreach {
      case '"' => sb.append("\\\"")
      case '\\' => sb.append("\\\\")
      case '\b' => sb.append("\\b")
      case '\f' => sb.append("\\f")
      case '\n' => sb.append("\\n")
      case '\r' => sb.append("\\r")
      case '\t' => sb.append("\\t")
      case c if c.isControl => sb.append(f"\\u${c.toInt}%04x")
      case c => sb.append(c)
    }
    sb.append('"')
    sb.toString
  }

  def render(value: Any, pretty: Boolean): String = {
    val indentSize = 2

    def spaces(n: Int): String = " " * n

    def render0(v: Any, depth: Int): String = v match {
      case null => "null"
      case s: String => escapeString(s)
      case b: Boolean => if (b) "true" else "false"

      case bd: BigDecimal => bd.toString
      case bd: java.math.BigDecimal => BigDecimal(bd).toString
      case bi: BigInt => bi.toString
      case n: Byte => n.toString
      case n: Short => n.toString
      case n: Int => n.toString
      case n: Long => n.toString
      case n: Float =>
        if (n.isNaN || n.isInfinite) throw new IllegalArgumentException("JSON does not support NaN/Infinity")
        java.lang.Float.toString(n)
      case n: Double =>
        if (n.isNaN || n.isInfinite) throw new IllegalArgumentException("JSON does not support NaN/Infinity")
        java.lang.Double.toString(n)

      case seq: Seq[?] =>
        val xs = seq.asInstanceOf[Seq[Any]]
        if (xs.isEmpty) "[]"
        else if (!pretty) xs.map(x => render0(x, depth + 1)).mkString("[", ",", "]")
        else {
          val inner = xs.map(x => spaces((depth + 1) * indentSize) + render0(x, depth + 1)).mkString(",\n")
          s"[\n$inner\n${spaces(depth * indentSize)}]"
        }

      case m: Map[?, ?] =>
        val obj = m.asInstanceOf[Map[Any, Any]].toList.map { case (k, vv) => k.toString -> vv }
        if (obj.isEmpty) "{}"
        else if (!pretty) {
          obj
            .map { case (k, vv) => s"${escapeString(k)}:${render0(vv, depth + 1)}" }
            .mkString("{", ",", "}")
        } else {
          val inner = obj
            .map { case (k, vv) =>
              spaces((depth + 1) * indentSize) + s"${escapeString(k)}: ${render0(vv, depth + 1)}"
            }
            .mkString(",\n")
          s"{\n$inner\n${spaces(depth * indentSize)}}"
        }

      case other =>
        throw new IllegalArgumentException(s"Unsupported JSON value: ${other.getClass.getName}")
    }

    render0(value, depth = 0)
  }
}

