// ==========================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { override val value: String = "string" }
  case object Numeric extends TokenType { override val value: String = "numeric" }
  case object Temporal extends TokenType { override val value: String = "temporal" }
  case object Structured extends TokenType { override val value: String = "structured" }
  case object Binary extends TokenType { override val value: String = "binary" }
  case object Null extends TokenType { override val value: String = "null" }

  val all: List[TokenType] = List(String, Numeric, Temporal, Structured, Binary, Null)

  def fromValue(v: String): Option[TokenType] = all.find(_.value == v)
}

// ==========================================================================
// Core token classes
// ==========================================================================

final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)

  def withMetadataMap(extra: Map[String, Any]): Token =
    copy(metadata = metadata ++ extra)
}

final class MutableTokenBatch(initial: Seq[Token] = Seq.empty) {
  private val buffer: mutable.ListBuffer[Token] = mutable.ListBuffer.from(initial)
  private var processed: Boolean = false

  def tokens: List[Token] = buffer.toList

  def add(token: ***REDACTED*** Unit = {
    if (processed) throw new IllegalStateException("Batch already processed")
    buffer += token
  }

  def markProcessed(): Unit = processed = true
}

// ==========================================================================
// Generic container classes (variance demonstrations)
// ==========================================================================

final class TokenContainer[+T](items: Seq[T]) {
  private val stored: Vector[T] = items.toVector

  def getAll: Vector[T] = stored

  def mapTokens(f: T => String): List[String] = stored.iterator.map(f).toList
}

final class TokenSink[-T] {
  private val received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: T): Unit = received += item

  def drain(): List[Any] = {
    val out = received.toList
    received.clear()
    out
  }
}

final class BivariantHandler[T](default: T) {
  private var current: T = default

  def get: T = current
  def set(value: T): Unit = current = value

  def transform(f: T => T): T = {
    current = f(current)
    current
  }
}

