  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def stripEdgePunctuation(s: String): String = {
    def dropLeading(x: String): String = x.dropWhile(punctuation.contains)
    def dropTrailing(x: String): String = x.reverse.dropWhile(punctuation.contains).reverse
    dropTrailing(dropLeading(s))
  }

