final case class TokenFunctor[+T](private val opt: Option[T]) {
  def map[U](f: T => U): TokenFunctor[U] = TokenFunctor(opt.map(f))

  def flatMap[U](f: T => TokenFunctor[U]): TokenFunctor[U] =
    TokenFunctor(opt.flatMap(t => f(t).opt))

  def getOrElse[U >: T](default: => U): U = opt.getOrElse(default)
}

object TokenFunctor {
  def apply[T](value: T): TokenFunctor[T] = TokenFunctor(Option(value))
}

final case class TokenMonad[+T](private val opt: Option[T]) {
  def map[U](f: T => U): TokenMonad[U] = TokenMonad(opt.map(f))

  def flatMap[U](f: T => TokenMonad[U]): TokenMonad[U] =
    TokenMonad(opt.flatMap(t => f(t).opt))

  def getOrElse[U >: T](default: => U): U = opt.getOrElse(default)

  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] =
    TokenMonad(for {
      f <- funcWrapped.opt
      v <- opt
    } yield f(v))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = TokenMonad(Option(value))
}

